const METADATA_ROUTES = new Set(["/robots.txt", "/sitemap.xml"]);

/**
 * Whether a path should bypass the hostname → route group rewrite.
 *
 * Exported so tests exercise the real predicate rather than a copy of it.
 */
export function skipsRouteGroupRewrite(pathname: string): boolean {
  if (METADATA_ROUTES.has(pathname)) {
    return false;
  }

  // Skip rewrites for static files, API routes, Next.js internals,
  // and standalone pages that live outside route groups
  return (
    pathname.startsWith("/_next") ||
    pathname.startsWith("/api") ||
    pathname.startsWith("/idx") || // PostHog proxy
    pathname.startsWith("/bible") || // Standalone whitepaper page
    pathname.includes(".") // Static files
  );
}

