/**
 * Map a hostname to the route group serving it.
 *
 * Dev tunnels are checked FIRST because *.dev.bartrhomes.com also ends with
 * .bartrhomes.com and would otherwise match marketing:
 * - www.joshua.dev.bartrhomes.com → marketing
 * - admin.joshua.dev.bartrhomes.com → admin
 * - app.joshua.dev.bartrhomes.com → app
 * - joshua.dev.bartrhomes.com → marketing (default, like bartrhomes.com in prod)
 */
function resolveRouteGroup(hostname: string): string {
  const hostWithoutPort = hostname.split(":")[0];

  if (hostWithoutPort.endsWith(DEV_TUNNEL_SUFFIX)) {
    const startsWithAny = (prefixes: readonly string[]) =>
      prefixes.some((prefix) => hostWithoutPort.startsWith(prefix));

    if (startsWithAny(DEV_TUNNEL_ADMIN_PREFIXES)) {
      return "site-admin";
    }
    if (startsWithAny(DEV_TUNNEL_APP_PREFIXES)) {
      return "site-app";
    }
    // www./marketing. and the bare tunnel both default to marketing, as in prod
    return "site-marketing";
  }

  // Use site-prefixed paths to avoid route conflicts
  // These are internal routing paths, not exposed in URLs
  if (
    matchesHost(hostname, [
      ...MARKETING_HOSTS,
      ...DEV_MARKETING_HOSTS,
      ...STAGING_MARKETING_HOSTS,
    ])
  ) {
    return "site-marketing";
  }
  if (
    matchesHost(hostname, [
      ...ADMIN_HOSTS,
      ...DEV_ADMIN_HOSTS,
      ...STAGING_ADMIN_HOSTS,
    ])
  ) {
    return "site-admin";
  }

  // App hosts and unknown hosts both fall through to the app
  return "site-app";
}

function getRouteGroupRewrite(
  request: NextRequest
): { rewrite: URL; routeGroup: string } | null {
  const { pathname } = request.nextUrl;

  if (skipsRouteGroupRewrite(pathname)) {
    return null;
  }

  // Support x-hostname-override header for staging/QA testing (non-production only)
  // This prevents hostname spoofing attacks in production
  const hostnameOverride = IS_PRODUCTION
    ? null
    : request.headers.get("x-hostname-override");
  const hostname = hostnameOverride || request.headers.get("host") || "";

  const routeGroup = resolveRouteGroup(hostname);

  if (skipsRouteGroupRewrite(pathname, routeGroup)) {
    return null;
  }

  const rewriteUrl = new URL(`/${routeGroup}${pathname}`, request.url);
  rewriteUrl.search = request.nextUrl.search;

  return { rewrite: rewriteUrl, routeGroup };
}

